try {
const store = $getWorkflowStaticData('global');
return [{ json: { offset: store.offset || 0 } }];
} catch (e) {
  let chat = null;
  try { chat = $('Conversación').first().json.chat_id; } catch (_) {}
  return [{ json: { chat_id: chat, texto: '⚠️ Algo salió mal en el bot (' + (e && e.message) + '). Toca "Menú" para empezar de nuevo.', teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];
}

// Toma la respuesta de getUpdates y deja pasar UN mensaje por ejecución (el resto se pide en la siguiente vuelta).
const store = $getWorkflowStaticData('global');
const resp = $input.first().json;
if (resp.ok === false) throw new Error(`Telegram respondió: ${resp.description || 'error'} (si dice "webhook is active", abre https://api.telegram.org/bot<TOKEN>/deleteWebhook una vez)`);
const updates = (resp.result || []).sort((a, b) => a.update_id - b.update_id);
if (updates.length === 0) return [];
const u = updates[0];
if (store.ultimo !== undefined && u.update_id <= store.ultimo) return []; // ya atendido: evita duplicados
store.ultimo = u.update_id;
store.offset = u.update_id + 1;
const m = u.message;
if (!m || !m.chat) return [];
return [{ json: { chat_id: m.chat.id, texto: m.text || '', nombre: (m.from && m.from.first_name) || '', update_id: u.update_id } }];

const MENU = { keyboard: [[{ text: 'Reservar' }], [{ text: 'Ver mi reserva' }], [{ text: 'Cancelar mi reserva' }]], resize_keyboard: true };
const FLUJO = { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true };
const ESTADOS = { pendiente: 'pendiente de confirmación', confirmada: 'confirmada', checkin: 'en curso (check-in)', checkout: 'finalizada', cancelada: 'cancelada', no_show: 'no se presentó' };
const mxn = (n) => `$${Number(n || 0).toFixed(2)} MXN`;

// ---------------- Conversación: menú + reservar / ver / cancelar ----------------
const entrada = $('Procesar mensaje').first().json;
const chatId = entrada.chat_id;
const texto = (entrada.texto || '').trim();
const cmd = texto.toLowerCase();
const nombreTg = entrada.nombre || '';
const store = $getWorkflowStaticData('global');
store.sesiones = store.sesiones || {};

const r = (accion, t, extra = {}) => [{ json: { chat_id: chatId, accion, texto: t, ...extra } }];
const preguntar = (t) => r('responder', t, { teclado: FLUJO });
const menu = (t) => r('responder', t, { teclado: MENU });
const saludo = () => `¡Hola ${nombreTg}! 👋 Soy el asistente del Hotel Casa Jaguar.\n¿Qué quieres hacer?\n\n1️⃣ Reservar\n2️⃣ Ver mi reserva\n3️⃣ Cancelar mi reserva\n\nToca un botón o responde con 1, 2 o 3.`;

const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Mexico_City' }).format(new Date());
function fechaISO(t) {
  let iso = null;
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(t);
  if (m) iso = `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = /^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/.exec(t);
  if (m) iso = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (!iso) return null;
  const d = new Date(`${iso}T00:00:00Z`);
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== iso ? null : iso;
}
const noches = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86400000);
const opcion = (c) => {
  if (['1', 'reservar', '/reservar', 'hacer reserva', 'quiero reservar'].includes(c)) return 'reservar';
  if (['2', 'ver mi reserva', 'ver reserva', 'ver', 'consultar', 'consultar reserva', '/ver'].includes(c)) return 'ver';
  if (['3', 'cancelar mi reserva', 'cancelar reserva'].includes(c)) return 'cancelar';
  return null;
};
const PEDIR_CODIGO = { ver: '¿Cuál es el código de tu reserva? (8 caracteres, por ejemplo 5A570577)', cancelar: 'Para cancelar necesito el código de tu reserva (8 caracteres, por ejemplo 5A570577).' };

if (!texto) return menu('Envíame un mensaje de texto, por favor.\n\n' + saludo());

// Volver al menú desde cualquier punto
if (['menu', 'menú', '/menu', '/start', '/salir', '/cancelar', 'salir', 'hola'].includes(cmd)) {
  delete store.sesiones[chatId];
  return menu(saludo());
}

let s = store.sesiones[chatId];
if (s && Date.now() - s.ts > 30 * 60 * 1000) s = null;

// Sin conversación en curso: se interpreta la opción del menú
if (!s) {
  const op = opcion(cmd);
  if (!op) return menu(saludo());
  if (op === 'reservar') {
    store.sesiones[chatId] = { op, paso: 'nombre', datos: {}, ts: Date.now() };
    return preguntar('Perfecto, vamos a reservar 🛎️\n\n¿Cuál es tu nombre (o nombres)?');
  }
  store.sesiones[chatId] = { op, paso: 'codigo', datos: {}, ts: Date.now() };
  return preguntar(PEDIR_CODIGO[op]);
}

s.ts = Date.now();
const d = s.datos;

switch (s.paso) {
  // ----- Reservar -----
  case 'nombre':
    if (texto.length < 2 || texto.length > 80) return preguntar('Escribe tu nombre (entre 2 y 80 caracteres).');
    d.nombre = texto; s.paso = 'apellidos';
    return preguntar('¿Y tus apellidos?');
  case 'apellidos':
    if (texto.length < 2 || texto.length > 100) return preguntar('Escribe tus apellidos (entre 2 y 100 caracteres).');
    d.apellidos = texto; s.paso = 'correo';
    return preguntar('¿Cuál es tu correo electrónico? (ahí te enviaremos la confirmación)');
  case 'correo':
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(texto)) return preguntar('Ese correo no parece válido. Ejemplo: nombre@correo.com');
    d.email = texto.toLowerCase(); s.paso = 'entrada';
    return preguntar('¿Qué día llegas? Escribe la fecha como AAAA-MM-DD (por ejemplo 2026-12-20) o DD/MM/AAAA.');
  case 'entrada': {
    const f = fechaISO(texto);
    if (!f) return preguntar('No entendí la fecha. Usa AAAA-MM-DD (2026-12-20) o DD/MM/AAAA.');
    if (f < hoy) return preguntar('La fecha de llegada no puede ser anterior a hoy. Intenta con otra.');
    d.entrada = f; s.paso = 'salida';
    return preguntar('¿Qué día te vas? (misma forma: AAAA-MM-DD)');
  }
  case 'salida': {
    const f = fechaISO(texto);
    if (!f) return preguntar('No entendí la fecha. Usa AAAA-MM-DD (2026-12-23) o DD/MM/AAAA.');
    if (f <= d.entrada) return preguntar(`La salida debe ser después de la llegada (${d.entrada}). Intenta de nuevo.`);
    if (noches(d.entrada, f) > 30) return preguntar('Por este medio solo se reservan hasta 30 noches. Escribe otra fecha de salida.');
    d.salida = f; s.paso = 'habitacion';
    return r('disponibilidad', '', { datos: { ...d } });
  }
  case 'habitacion': {
    const numero = texto.replace(/^hab(itaci[oó]n)?\s*/i, '').trim();
    const hab = (s.disponibles || []).find((h) => String(h.numero).toLowerCase() === numero.toLowerCase());
    if (!hab) return preguntar(`No encontré esa habitación. Elige una de estas: ${(s.disponibles || []).map((h) => h.numero).join(', ')}.`);
    Object.assign(d, { habitacionId: hab.habitacionId, numero: hab.numero, tipo: hab.tipo, numAdultos: Math.min(2, hab.capacidad), total: noches(d.entrada, d.salida) * hab.precioBase });
    s.paso = 'confirmar_reserva';
    return preguntar(`Confirma tu reserva:\n👤 ${d.nombre} ${d.apellidos}\n📧 ${d.email}\n🛏️ Habitación ${d.numero} (${d.tipo}) para ${d.numAdultos} adulto(s)\n📅 Entrada: ${d.entrada}\n📅 Salida: ${d.salida} (${noches(d.entrada, d.salida)} noche(s))\n💰 Total: ${mxn(d.total)}\n\nResponde SI para confirmar o NO para salir.`);
  }
  case 'confirmar_reserva':
    if (['si', 'sí', 's', 'confirmo', 'confirmar'].includes(cmd)) {
      delete store.sesiones[chatId];
      return r('registrar', '', { datos: { ...d, telegramChatId: chatId } });
    }
    if (cmd === 'no') { delete store.sesiones[chatId]; return menu('De acuerdo, no registré nada.\n\n' + saludo()); }
    return preguntar('Responde SI para confirmar o NO para salir.');

  // ----- Ver / Cancelar -----
  case 'codigo': {
    const c = texto.toUpperCase();
    if (!/^[0-9A-F]{8}$/.test(c)) return preguntar('Ese código no es válido. Son 8 caracteres (números y letras A-F), por ejemplo 5A570577.');
    d.codigo = c; s.paso = 'correo_reserva';
    return preguntar('Por seguridad, escribe el correo con el que hiciste la reserva.');
  }
  case 'correo_reserva':
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(texto)) return preguntar('Ese correo no parece válido. Ejemplo: nombre@correo.com');
    d.email = texto.toLowerCase();
    s.paso = s.op === 'ver' ? 'ver_espera' : 'cancelar_espera';
    return r('buscar', '', { datos: { codigo: d.codigo, email: d.email, modo: s.op } });
  case 'cancelar_confirmar':
    if (['si', 'sí', 's', 'confirmo', 'confirmar'].includes(cmd)) {
      delete store.sesiones[chatId];
      return r('cancelar', '', { datos: { reservaId: s.reservaId, codigo: d.codigo, email: d.email } });
    }
    if (cmd === 'no') { delete store.sesiones[chatId]; return menu('Listo, tu reserva sigue vigente 👍\n\n' + saludo()); }
    return preguntar('Responde SI para cancelar la reserva o NO para conservarla.');

  case 'confirmar_pendiente':
    if (['si', 'sí', 's', 'confirmo', 'confirmar'].includes(cmd)) {
      delete store.sesiones[chatId];
      return r('confirmar', '', { datos: { reservaId: s.reservaId, codigo: d.codigo } });
    }
    if (cmd === 'no') { delete store.sesiones[chatId]; return menu('Está bien, tu reserva sigue pendiente. Puedes confirmarla después desde "Ver mi reserva".\n\n' + saludo()); }
    return preguntar('Responde SI para confirmar tu reserva o NO para dejarla pendiente.');

  default:
    delete store.sesiones[chatId];
    return menu('Algo salió mal; empecemos de nuevo.\n\n' + saludo());
}

const c = $('Conversación').first().json;
const r = $input.first().json;
const motivo = r.statusCode ? `el sistema respondió ${r.statusCode}${r.body && r.body.error ? ': ' + r.body.error : ''}` : 'no se pudo conectar con el sistema';
return [{ json: { chat_id: c.chat_id, texto: `⚠️ El bot no pudo iniciar sesión en el sistema (${motivo}). Avisa a recepción.`, teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];

try {
const MENU = { keyboard: [[{ text: 'Reservar' }], [{ text: 'Ver mi reserva' }], [{ text: 'Cancelar mi reserva' }]], resize_keyboard: true };
const FLUJO = { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true };
const ESTADOS = { pendiente: 'pendiente de confirmación', confirmada: 'confirmada', checkin: 'en curso (check-in)', checkout: 'finalizada', cancelada: 'cancelada', no_show: 'no se presentó' };
const mxn = (n) => `$${Number(n || 0).toFixed(2)} MXN`;

// Respuestas del PMS (con "full response"): { statusCode, body }. Se normalizan a listas/objetos simples.
const cuerpo = (items) => items.map((i) => i.json).flatMap((j) => { const b = j && j.statusCode !== undefined && 'body' in j ? j.body : j; return Array.isArray(b) ? b : [b]; });
const fallo = (items) => items.map((i) => i.json).find((j) => j && typeof j.statusCode === 'number' && j.statusCode >= 400);
const motivoFallo = (j) => `${j.statusCode}${j.body && j.body.error ? ': ' + j.body.error : ''}`;
// Habitaciones libres -> se guardan en la sesión para validar la elección
const chatId = $('Conversación').first().json.chat_id;
const store = $getWorkflowStaticData('global');
store.sesiones = store.sesiones || {};
const s = store.sesiones[chatId];
// La API responde { entrada, salida, noches, disponibles: [...] }; se acepta también una lista de habitaciones sueltas.
const errorApi = fallo($input.all());
if (errorApi) return [{ json: { chat_id: chatId, texto: `⚠️ No pude consultar la disponibilidad (${motivoFallo(errorApi)}). Inténtalo de nuevo en un momento o toca Menú.`, teclado: FLUJO } }];
const libres = cuerpo($input.all()).flatMap((j) => (j && Array.isArray(j.disponibles) ? j.disponibles : [j])).filter((h) => h && h.habitacionId !== undefined);
if (!s) return [{ json: { chat_id: chatId, texto: 'La sesión expiró. Toca "Reservar" para empezar de nuevo.', teclado: MENU } }];
if (libres.length === 0) {
  s.paso = 'entrada';
  return [{ json: { chat_id: chatId, texto: 'No hay habitaciones libres en esas fechas 😕. Escribe otra fecha de llegada (AAAA-MM-DD) o toca Menú.', teclado: FLUJO } }];
}
s.disponibles = libres;
const d = s.datos;
const n = Math.round((Date.parse(`${d.salida}T00:00:00Z`) - Date.parse(`${d.entrada}T00:00:00Z`)) / 86400000);
const filas = libres.map((h) => `🛏️ ${h.numero} · ${h.tipo} · hasta ${h.capacidad} pers. · ${mxn(h.precioBase)}/noche`);
return [{ json: { chat_id: chatId, texto: `Habitaciones libres del ${d.entrada} al ${d.salida} (${n} noche(s)):\n\n${filas.join('\n')}\n\nEscribe el número de la habitación que quieres (por ejemplo 101).`, teclado: FLUJO } }];

} catch (e) {
  let chat = null;
  try { chat = $('Conversación').first().json.chat_id; } catch (_) {}
  return [{ json: { chat_id: chat, texto: '⚠️ Algo salió mal en el bot (' + (e && e.message) + '). Toca "Menú" para empezar de nuevo.', teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];
}

try {
const email = String($('Conversación').first().json.datos.email || '').trim().toLowerCase();
const lista = $input.all().map((i) => i.json).flatMap((j) => { const b = j && j.statusCode !== undefined && 'body' in j ? j.body : j; return Array.isArray(b) ? b : [b]; });
const existente = lista.find((g) => g && g.email && String(g.email).trim().toLowerCase() === email);
return [{ json: { huespedId: existente ? existente.id : null } }];
} catch (e) {
  let chat = null;
  try { chat = $('Conversación').first().json.chat_id; } catch (_) {}
  return [{ json: { chat_id: chat, texto: '⚠️ Algo salió mal en el bot (' + (e && e.message) + '). Toca "Menú" para empezar de nuevo.', teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];
}

try {
const prev = $input.first().json;
const d = $('Conversación').first().json.datos;
const huespedId = prev.huespedId != null ? prev.huespedId : (prev.body && prev.body.id);
return [{ json: { reserva: {
  huespedId,
  fechaEntrada: d.entrada,
  fechaSalida: d.salida,
  numAdultos: d.numAdultos,
  origen: 'telegram',
  estado: 'pendiente',
  notas: 'Reserva hecha por el bot de Telegram',
  habitaciones: [{ habitacionId: d.habitacionId }],
} } }];
} catch (e) {
  let chat = null;
  try { chat = $('Conversación').first().json.chat_id; } catch (_) {}
  return [{ json: { chat_id: chat, texto: '⚠️ Algo salió mal en el bot (' + (e && e.message) + '). Toca "Menú" para empezar de nuevo.', teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];
}

try {
const MENU = { keyboard: [[{ text: 'Reservar' }], [{ text: 'Ver mi reserva' }], [{ text: 'Cancelar mi reserva' }]], resize_keyboard: true };
const FLUJO = { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true };
const ESTADOS = { pendiente: 'pendiente de confirmación', confirmada: 'confirmada', checkin: 'en curso (check-in)', checkout: 'finalizada', cancelada: 'cancelada', no_show: 'no se presentó' };
const mxn = (n) => `$${Number(n || 0).toFixed(2)} MXN`;

// Resultado de crear la reserva (201 = creada) + resultado del envío del correo con el QR (lo hace este flujo).
const c = $('Conversación').first().json;
const d = c.datos;
const res = $('Crear reserva').first().json; // { statusCode, body }
const mail = $input.first().json; // respuesta de "Enviar correo con QR" { statusCode, body }
if (res.statusCode === 201) {
  const b = res.body;
  const enviado = mail && mail.statusCode === 200;
  const correo = enviado
    ? `\n\n📧 Te enviamos la confirmación con tu código QR a ${d.email}. Preséntalo en recepción.`
    : `\n\n⚠️ No pude enviar el correo con tu QR. Guarda tu código ${b.codigo}: con él recepción te atiende igual.`;
  return [{ json: {
    chat_id: c.chat_id,
    texto: `✅ ¡Reserva registrada!\n🔖 Código: ${b.codigo}\n👤 ${d.nombre} ${d.apellidos}\n🛏️ Habitación ${d.numero} (${d.tipo})\n📅 Entrada: ${d.entrada}\n📅 Salida: ${d.salida}\n💰 Total: ${mxn(b.total)}\n📌 Estado: pendiente (recepción la confirmará)${correo}\n\nPuedes consultarla, confirmarla o cancelarla desde el menú con tu código.`,
    teclado: MENU,
  } }];
}
const motivo = res.statusCode === 409
  ? '😕 Esa habitación ya no está disponible para esas fechas (alguien la acaba de reservar). Toca "Reservar" para intentar de nuevo.'
  : `⚠️ No pude registrar la reserva: ${(res.body && res.body.error) || 'error inesperado'}. Toca "Reservar" para intentar de nuevo.`;
return [{ json: { chat_id: c.chat_id, texto: motivo, teclado: MENU } }];

} catch (e) {
  let chat = null;
  try { chat = $('Conversación').first().json.chat_id; } catch (_) {}
  return [{ json: { chat_id: chat, texto: '⚠️ Algo salió mal en el bot (' + (e && e.message) + '). Toca "Menú" para empezar de nuevo.', teclado: { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true } } }];
}

try {
const MENU = { keyboard: [[{ text: 'Reservar' }], [{ text: 'Ver mi reserva' }], [{ text: 'Cancelar mi reserva' }]], resize_keyboard: true };
const FLUJO = { keyboard: [[{ text: 'Menú' }]], resize_keyboard: true };
const ESTADOS = { pendiente: 'pendiente de confirmación', confirmada: 'confirmada', checkin: 'en curso (check-in)', checkout: 'finalizada', cancelada: 'cancelada', no_show: 'no se presentó' };
const mxn = (n) => `$${Number(n || 0).toFixed(2)} MXN`;

// Respuestas del PMS (con "full response"): { statusCode, body }. Se normalizan a listas/objetos simples.
const cuerpo = (items) => items.map((i) => i.json).flatMap((j) => { const b = j && j.statusCode !== undefined && 'body' in j ? j.body : j; return Array.isArray(b) ? b : [b]; });
const fallo = (items) => items.map((i) => i.json).find((j) => j && typeof j.statusCode === 'number' && j.statusCode >= 400);
const motivoFallo = (j) => `${j.statusCode}${j.body && j.body.error ? ': ' + j.body.error : ''}`;

// Ver / Cancelar: localiza la reserva y comprueba que el correo sea del titular
const c = $('Conversación').first().json;
const d = c.datos;
const store = $getWorkflowStaticData('global');
store.sesiones = store.sesiones || {};
const s = store.sesiones[c.chat_id];
const salida = (texto, teclado) => [{ json: { chat_id: c.chat_id, texto, teclado } }];
const errorApi = fallo($('Buscar reserva').all()) || fallo($input.all());
if (errorApi) {
  delete store.sesiones[c.chat_id];
  return salida(`⚠️ No pude consultar tu reserva (${motivoFallo(errorApi)}). Inténtalo de nuevo desde el menú o comunícate con recepción.`, MENU);
}
const mismo = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
const reservas = cuerpo($('Buscar reserva').all()).filter((x) => x && x.codigo);
const huespedes = cuerpo($input.all()).filter((g) => g && g.email);
const titular = huespedes.find((g) => mismo(g.email, d.email));
const rsv = reservas.find((x) => mismo(x.codigo, d.codigo) && titular && x.huespedId === titular.id);

if (!rsv) {
  delete store.sesiones[c.chat_id];
  return salida('❌ No encontré una reserva con ese código y ese correo. Revisa los datos e inténtalo de nuevo desde el menú.', MENU);
}
const habs = (rsv.habitaciones || []).map((h) => `${h.numero} (${h.tipo})`).join(', ') || 'Sin asignar';
const detalle = `🔖 Reserva ${rsv.codigo}\n👤 ${rsv.huespedNombre}\n🛏️ Habitación: ${habs}\n📅 Entrada: ${rsv.fechaEntrada}\n📅 Salida: ${rsv.fechaSalida}\n📌 Estado: ${ESTADOS[rsv.estado] || rsv.estado}\n💰 Total: ${mxn(rsv.total)}\n💳 Pagado: ${mxn(rsv.totalPagado)}\n🧾 Saldo pendiente: ${mxn(rsv.saldo)}`;

if (d.modo === 'ver') {
  const qr = { qr_reserva_id: rsv.id, qr_codigo: rsv.codigo };
  if (rsv.estado === 'pendiente' && s) {
    s.paso = 'confirmar_pendiente';
    s.reservaId = rsv.id;
    return [{ json: { chat_id: c.chat_id, teclado: FLUJO, ...qr,
      texto: `${detalle}\n\n¿Quieres confirmar tu reserva ahora? Responde SI para confirmarla o NO para dejarla pendiente.\nTe mando también tu código QR.` } }];
  }
  delete store.sesiones[c.chat_id];
  return [{ json: { chat_id: c.chat_id, teclado: MENU, ...qr,
    texto: `${detalle}\n\nA continuación te mando el código QR de tu reserva.` } }];
}

if (!['pendiente', 'confirmada'].includes(rsv.estado)) {
  delete store.sesiones[c.chat_id];
  return salida(`${detalle}\n\nEsta reserva está "${ESTADOS[rsv.estado] || rsv.estado}" y no se puede cancelar por este medio. Comunícate con recepción.`, MENU);
}
if (!s) return salida('La sesión expiró. Toca "Cancelar mi reserva" para empezar de nuevo.', MENU);
s.paso = 'cancelar_confirmar';
s.reservaId = rsv.id;
return salida(`${detalle}\n\n¿Confirmas la cancelación de esta reserva? Responde SI o NO.`, FLUJO);

